		fmt.Println("Usage: go run parser.go <input_file> <output_file>")
		os.Exit(1)
	}

	inputFile := os.Args[1]
	outputFile := os.Args[2]

	file, err := os.Open(inputFile)
	if err != nil {
		fmt.Printf("Error opening file %s: %v\n", inputFile, err)
		return
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	var structSchema *schema.Schema

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "type:" && !scanner.Scan() { // Look for 'type:' keyword
			continue
		}
		if scanner.Scan() && scanner.Text() == "}" { // End of struct definition
			break
		}
	}

	if err := scanner.Err(); err != nil {
		fmt.Printf("Error scanning file %s: %v\n", inputFile, err)
		return
	}

	structName := "Struct"
	structType := fmt.Sprintf("%s=%s;", structName, schema.TypeMap{"type": "record", "name": structName})
	structSchema = &schema.Schema{
		Name:   structName,
		Type:   schema.Record{Name: structName},
	 Fields: []schema.Field{},
	}

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "{" || line == "}" {
			continue
		}

		fieldName := ""
		fieldType := ""

		split := strings.FieldsFunc(line, func(c rune) bool {
			return c == ':'
		})

		if len(split) > 0 {
			fieldName = split[0]
		}

		if len(split) > 1 {
			fieldType = split[1]
		}

		if fieldName != "" && fieldType != "" {
			structField := schema.Field{Name: fieldName, Type: fieldType}
			structSchema.Fields = append(structSchema.Fields, structField)
		}
	}

	err = writeAvroSchemaToFile(outputFile, structSchema)
	if err != nil {
		fmt.Printf("Error writing Avro schema to file %s: %v\n", outputFile, err)
		return
	}

	fmt.Printf("Successfully generated Avro schema at %s\n", outputFile)
}

func writeAvroSchemaToFile(filename string, schema *schema.Schema) error {
	f, err := os.Create(filename)
	if err != nil {
		return err
	}
	defer f.Close()

	writer := schema.NewJsonWriter(f)
	if err := writer.Write(schema); err != nil {
		return err
	}

	return nil
}
