import javax.sound.sampled.*;
import java.io.*;

public class SummerDayAudio {
    public static void main(String[] args) throws Exception {
        // Load audio clips
        Clip clipBirdChirp = AudioSystem.getClip();
        clipBirdChirp.open(new File("bird_chirp.wav"));
        Clip clipLeafRustle = AudioSystem.getClip();
        clipLeafRustle.open(new File("leaf_rustle.wav"));
        Clip clipCicadaHum = AudioSystem.getClip();
        clipCicadaHum.open(new File("cicada_hum.wav"));

        // Define audio segments
        String[] scenes = {"picnic", "beach"};
        double[][] segmentTimes = {{0, 30}, {30, 60}};

