        int currentSceneIndex = 0;
        while (!clipBirdChirp.isCancelled() && !clipLeafRustle.isCancelled() && !clipCicadaHum.isCancelled()) {
            playSegment(clipBirdChirp, segmentTimes[currentSceneIndex][0], segmentTimes[currentSceneIndex][1]);
            playSegment(clipLeafRustle, segmentTimes[currentSceneIndex + 1][0], segmentTimes[currentSceneIndex + 1][1]);
            playSegment(clipCicadaHum, segmentTimes[currentSceneIndex + 2][0], segmentTimes[currentSceneIndex + 2][1]);

            currentSceneIndex++;
            if (currentSceneIndex >= scenes.length)
                break;
        }

        // Cleanup
        clipBirdChirp.close();
        clipLeafRustle.close();
        clipCicadaHum.close();
    }

    private static void playSegment(Clip clip, double startTime, double endTime) throws InterruptedException {
        clip.setFramePosition((int)(startTime * clip.getFormat().getSampleRate()));
        Thread.sleep((int)((endTime - startTime) * clip.getFormat().getSampleRate()));
        clip.start();
    }
}
